
import argparse
import json
import subprocess
import sys
from datetime import datetime
from pathlib import Path

ROOT = Path(__file__).resolve().parent
SINGLE_SCRIPT = ROOT / "udise_daily_refresh.py"
REPORT_DIR = ROOT / "reports" / "udise_refresh"

DEFAULT_CODES = [
    "07060208102",
    "07060209108",
    "07060308202",
    "07060208307",
    "07060209204",
]


def read_school_report(stdout):
    """Read the individual report generated by the existing script."""
    for line in stdout.splitlines():
        if line.startswith("Report saved: "):
            report_path = Path(line.partition(": ")[2].strip())

            if not report_path.is_absolute():
                report_path = ROOT / report_path

            if report_path.is_file():
                with report_path.open("r", encoding="utf-8") as file:
                    return report_path, json.load(file)

    return None, None


def main():
    parser = argparse.ArgumentParser(
        description="Run safe UDISE refreshes for multiple schools."
    )
    parser.add_argument(
        "--udise",
        action="append",
        help="UDISE code to process; repeat this option for multiple codes.",
    )
    parser.add_argument(
        "--apply",
        action="store_true",
        help="Apply changes after creating and verifying backups.",
    )
    args = parser.parse_args()

    codes = args.udise if args.udise else DEFAULT_CODES

    if not SINGLE_SCRIPT.is_file():
        parser.error("udise_daily_refresh.py was not found.")

    if len(codes) != len(set(codes)):
        parser.error("Duplicate UDISE codes found. Remove duplicates.")

    for code in codes:
        if len(code) != 11 or not code.isdigit():
            parser.error(f"Invalid UDISE code: {code}")

    mode = "APPLY" if args.apply else "DRY RUN"

    print("=" * 72)
    print("UDISE+ BATCH REFRESH")
    print(f"Mode: {mode}")
    print(f"Schools: {len(codes)}")
    print("=" * 72)

    results = []

    for index, code in enumerate(codes, start=1):
        print(f"\n[{index}/{len(codes)}] Processing UDISE: {code}")
        command = [
            sys.executable,
            str(SINGLE_SCRIPT),
            "--udise",
            code,
        ]

        if args.apply:
            command.append("--apply")

        process = subprocess.run(
            command,
            cwd=ROOT,
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
        )

        if process.stdout:
            print(process.stdout, end="")

        if process.stderr:
            print("ERROR OUTPUT:")
            print(process.stderr)

        report_path, report = read_school_report(process.stdout)

        result = {
            "udise_code": code,
            "process_exit_code": process.returncode,
            "process_status": (
                "completed" if process.returncode == 0 else "script_error"
            ),
            "report_path": (
                str(report_path.relative_to(ROOT))
                if report_path and report_path.is_relative_to(ROOT)
                else str(report_path) if report_path else None
            ),
        }

        if report is not None:
            sections = report.get("sections", {})
            result.update({
                "school_name": report.get("school_name"),
                "successful_sections": report.get("successful_sections", 0),
                "changed_fields_count": len(
                    report.get("changed_fields", [])
                ),
                "failed_sections": [
                    name
                    for name, details in sections.items()
                    if details.get("status") == "failed"
                ],
                "raw_file_updated": report.get("raw_file_updated", False),
            })

        results.append(result)

    REPORT_DIR.mkdir(parents=True, exist_ok=True)
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S_%f")
    batch_report_path = REPORT_DIR / f"batch_udise_{timestamp}.json"

    batch_report = {
        "generated_at": datetime.now().astimezone().isoformat(),
        "mode": mode,
        "schools_requested": len(codes),
        "schools_processed": len(results),
        "results": results,
    }

    with batch_report_path.open("w", encoding="utf-8") as file:
        json.dump(batch_report, file, indent=4, ensure_ascii=False)
        file.write("\n")

    print("\n" + "=" * 72)
    print("BATCH SUMMARY")

    for result in results:
        print(
            f"{result['udise_code']}: "
            f"{result['process_status']}, "
            f"successful sections="
            f"{result.get('successful_sections', 'report unavailable')}, "
            f"changed fields="
            f"{result.get('changed_fields_count', 'unknown')}, "
            f"raw updated={result.get('raw_file_updated', False)}"
        )

    print(f"\nBatch report: {batch_report_path}")
    print("Review individual reports before applying any changes.")
    print("=" * 72)

    if any(item["process_status"] != "completed" for item in results):
        raise SystemExit(1)


if __name__ == "__main__":
    main()
